// 典籍文库 · 随包精选集（文库层骨架）。
// 全部公版原文，字段与 canon_work 表一一对应；source 标注底本。
// 规模约定（docs/传统文化与音乐学习模式方案 §4.2b / §4.8 遗留②）：本文件 ≥180 篇、
// 先秦到明清九个朝代段每段 ≥10 篇（canon-store.test.ts 钉死），notable 冷门佳作 ≥25 篇。
// ★ 收录纪律：只收能逐字准确写出原文的公版名篇——一字不确定就不收（教学事故优先级高于数量）；
//   长文（赋/散文）节选并在 title 标「（节选）」。完整断代大库仍由 scripts/import-canon.mjs
//   从 tools/canon-src/（chinese-poetry 等，MIT/CC 公版）分批导入，本文件不动。
// popularity 口径：classic=教材/名句入选；notable=冷门佳作（选本与评点收录）；
// normal=普通篇目。此名单离线预生成，不靠运行时热度。

import type { CanonWork } from './types';

const W = (w: CanonWork): CanonWork => w;

export const CANON_SEED_WORKS: CanonWork[] = [
  // ── 先秦（经部与骚体）───────────────────────────────────────
  W({ id: 'canon_sj_guanju', title: '关雎', author: '佚名', dynasty: '先秦', genre: '经', collection: '诗经', tags: ['爱情', '起兴'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '关关雎鸠，在河之洲。窈窕淑女，君子好逑。\n参差荇菜，左右流之。窈窕淑女，寤寐求之。\n求之不得，寤寐思服。悠哉悠哉，辗转反侧。' }),
  W({ id: 'canon_sj_jianjia', title: '蒹葭（节选）', author: '佚名', dynasty: '先秦', genre: '经', collection: '诗经', tags: ['怀人', '秋水'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '蒹葭苍苍，白露为霜。所谓伊人，在水一方。\n溯洄从之，道阻且长。溯游从之，宛在水中央。' }),
  W({ id: 'canon_sj_taoyao', title: '桃夭（节选）', author: '佚名', dynasty: '先秦', genre: '经', collection: '诗经', tags: ['婚嫁', '祝福'], popularity: 'normal', difficulty: '蒙学', source: '通行本', text: '桃之夭夭，灼灼其华。之子于归，宜其室家。' }),
  W({ id: 'canon_sj_shuo', title: '硕鼠（节选）', author: '佚名', dynasty: '先秦', genre: '经', collection: '诗经', tags: ['讽刺', '民本'], popularity: 'notable', difficulty: '进阶', source: '通行本', text: '硕鼠硕鼠，无食我黍！三岁贯女，莫我肯顾。\n逝将去女，适彼乐土。乐土乐土，爰得我所。' }),
  W({ id: 'canon_ly_xueer_shouzhang', title: '论语 · 学而（首章）', author: '孔子及弟子', dynasty: '先秦', genre: '经', collection: '论语', tags: ['为学', '修身'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '学而时习之，不亦说乎？有朋自远方来，不亦乐乎？人不知而不愠，不亦君子乎？' }),
  W({ id: 'canon_laoz_shangshan', title: '老子（节选）', author: '老子', dynasty: '先秦', genre: '经', collection: '道德经', tags: ['哲理'], popularity: 'classic', difficulty: '深造', source: '通行本', text: '上善若水。水善利万物而不争，处众人之所恶，故几于道。' }),
  W({ id: 'canon_zz_beiming', title: '庄子 · 逍遥游（节选）', author: '庄子', dynasty: '先秦', genre: '文', collection: '庄子', tags: ['寓言', '哲理'], popularity: 'classic', difficulty: '深造', source: '通行本', text: '北冥有鱼，其名为鲲。鲲之大，不知其几千里也。化而为鸟，其名为鹏。鹏之背，不知其几千里也。' }),
  W({ id: 'canon_yuerenge', title: '越人歌', author: '佚名', dynasty: '先秦', genre: '诗', collection: '', tags: ['抒情', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本（《说苑》引）', text: '今夕何夕兮，搴舟中流。今日何日兮，得与王子同舟。\n蒙羞被好兮，不訾诟耻。心几烦而不绝兮，得知王子。' }),
  W({ id: 'canon_sj_fatan', title: '伐檀（节选）', author: '佚名', dynasty: '先秦', genre: '经', collection: '诗经', tags: ['讽刺', '民本', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本', text: '坎坎伐檀兮，置之河之干兮，河水清且涟猗。\n不稼不穑，胡取禾三百廛兮？不狩不猎，胡瞻尔庭有县貆兮？\n彼君子兮，不素餐兮！' }),
  W({ id: 'canon_sj_mugua', title: '木瓜', author: '佚名', dynasty: '先秦', genre: '经', collection: '诗经', tags: ['赠答', '情谊'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '投我以木瓜，报之以琼琚。匪报也，永以为好也！\n投我以木桃，报之以琼瑶。匪报也，永以为好也！\n投我以木李，报之以琼玖。匪报也，永以为好也！' }),
  W({ id: 'canon_sj_caiwei', title: '采薇（节选）', author: '佚名', dynasty: '先秦', genre: '经', collection: '诗经', tags: ['戍边', '杨柳'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '昔我往矣，杨柳依依。今我来思，雨雪霏霏。' }),
  W({ id: 'canon_sj_qiao', title: '淇奥（节选）', author: '佚名', dynasty: '先秦', genre: '经', collection: '诗经', tags: ['君子', '修身', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本', text: '瞻彼淇奥，绿竹猗猗。有匪君子，如切如磋，如琢如磨。' }),
  W({ id: 'canon_lisao_qiulu', title: '离骚（节选）', author: '屈原', dynasty: '先秦', genre: '诗', collection: '楚辞', tags: ['求索', '志向'], popularity: 'classic', difficulty: '深造', source: '通行本', text: '路漫漫其修远兮，吾将上下而求索。\n亦余心之所善兮，虽九死其犹未悔。' }),
  W({ id: 'canon_lunyu_weizheng', title: '论语 · 为政（节选）', author: '孔子及弟子', dynasty: '先秦', genre: '经', collection: '论语', tags: ['为学', '思考'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '温故而知新，可以为师矣。\n学而不思则罔，思而不学则殆。' }),
  W({ id: 'canon_mengzi_dazhangfu', title: '孟子 · 滕文公下（节选）', author: '孟子及弟子', dynasty: '先秦', genre: '经', collection: '孟子', tags: ['气节', '大丈夫'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '富贵不能淫，贫贱不能移，威武不能屈，此之谓大丈夫。' }),
  W({ id: 'canon_lijix_xueji', title: '礼记 · 学记（节选）', author: '佚名', dynasty: '先秦', genre: '经', collection: '礼记', tags: ['教学', '哲理'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '玉不琢，不成器；人不学，不知道。是故古之王者建国君民，教学为先。' }),
  W({ id: 'canon_zhouyi_qian', title: '周易 · 乾卦 · 象传（节选）', author: '佚名', dynasty: '先秦', genre: '经', collection: '周易', tags: ['自强', '哲理'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '天行健，君子以自强不息。' }),

  // ── 两汉（乐府）────────────────────────────────────────────
  W({ id: 'canon_han_jiangnan', title: '江南', author: '汉乐府', dynasty: '两汉', genre: '诗', collection: '乐府诗集', tags: ['采莲', '民歌'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '江南可采莲，莲叶何田田。鱼戏莲叶间。\n鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。' }),
  W({ id: 'canon_han_changgexing', title: '长歌行', author: '汉乐府', dynasty: '两汉', genre: '诗', collection: '乐府诗集', tags: ['惜时', '劝学'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '青青园中葵，朝露待日晞。阳春布德泽，万物生光辉。\n常恐秋节至，焜黄华叶衰。百川东到海，何时复西归？\n少壮不努力，老大徒伤悲。' }),
  W({ id: 'canon_gushi_xingxing', title: '行行重行行', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['离别', '思念'], popularity: 'classic', difficulty: '进阶', source: '通行本（《文选》）', text: '行行重行行，与君生别离。相去万余里，各在天一涯。\n道路阻且长，会面安可知？胡马依北风，越鸟巢南枝。\n相去日已远，衣带日已缓。浮云蔽白日，游子不顾返。\n思君令人老，岁月忽已晚。弃捐勿复道，努力加餐饭。' }),
  W({ id: 'canon_han_shangye', title: '上邪', author: '汉乐府', dynasty: '两汉', genre: '诗', collection: '乐府诗集', tags: ['爱情', '誓言', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本', text: '上邪！我欲与君相知，长命无绝衰。\n山无陵，江水为竭，冬雷震震，夏雨雪，天地合，乃敢与君绝。' }),
  W({ id: 'canon_gushi_qingqinghepan', title: '青青河畔草', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['思念', '闺怨'], popularity: 'normal', difficulty: '进阶', source: '通行本（《文选》）', text: '青青河畔草，郁郁园中柳。盈盈楼上女，皎皎当窗牖。\n娥娥红粉妆，纤纤出素手。昔为倡家女，今为荡子妇。\n荡子行不归，空床难独守。' }),
  W({ id: 'canon_gushi_qingqinglingshang', title: '青青陵上柏', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['人生', '感慨'], popularity: 'normal', difficulty: '进阶', source: '通行本（《文选》）', text: '青青陵上柏，磊磊涧中石。人生天地间，忽如远行客。\n斗酒相娱乐，聊厚不为薄。驱车策驽马，游戏宛与洛。\n洛中何郁郁，冠带自相索。长衢罗夹巷，王侯多第宅。\n两宫遥相望，双阙百余尺。极宴娱心意，戚戚何所迫。' }),
  W({ id: 'canon_gushi_jinri', title: '今日良宴会', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['宴饮', '人生'], popularity: 'normal', difficulty: '进阶', source: '通行本（《文选》）', text: '今日良宴会，欢乐难具陈。弹筝奋逸响，新声妙入神。\n令德唱高言，识曲听其真。齐心同所愿，含意俱未申。\n人生寄一世，奄忽若飙尘。何不策高足，先据要路津。\n无为守贫贱，坎坷长苦辛。' }),
  W({ id: 'canon_gushi_xibei', title: '西北有高楼', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['知音', '弦歌'], popularity: 'normal', difficulty: '深造', source: '通行本（《文选》）', text: '西北有高楼，上与浮云齐。交疏结绮窗，阿阁三重阶。\n上有弦歌声，音响一何悲！谁能为此曲，无乃杞梁妻。\n清商随风发，中曲正徘徊。一弹再三叹，慷慨有余哀。\n不惜歌者苦，但伤知音稀。愿为双鸿鹄，奋翅起高飞。' }),
  W({ id: 'canon_gushi_shejiang', title: '涉江采芙蓉', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['思念', '离别'], popularity: 'classic', difficulty: '进阶', source: '通行本（《文选》）', text: '涉江采芙蓉，兰泽多芳草。采之欲遗谁，所思在远道。\n还顾望旧乡，长路漫浩浩。同心而离居，忧伤以终老。' }),
  W({ id: 'canon_gushi_mingyuejiao', title: '明月皎夜光', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['秋夜', '交情'], popularity: 'normal', difficulty: '深造', source: '通行本（《文选》）', text: '明月皎夜光，促织鸣东壁。玉衡指孟冬，众星何历历。\n白露沾野草，时节忽复易。秋蝉鸣树间，玄鸟逝安适。\n昔我同门友，高举振六翮。不念携手好，弃我如遗迹。\n南箕北有斗，牵牛不负轭。良无盘石固，虚名复何益。' }),
  W({ id: 'canon_gushi_ranran', title: '冉冉孤生竹', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['婚恋', '思念'], popularity: 'normal', difficulty: '深造', source: '通行本（《文选》）', text: '冉冉孤生竹，结根泰山阿。与君为新婚，菟丝附女萝。\n菟丝生有时，夫妇会有宜。千里远结婚，悠悠隔山陂。\n思君令人老，轩车来何迟。伤彼蕙兰花，含英扬光辉。\n过时而不采，将随秋草萎。君亮执高节，贱妾亦何为。' }),
  W({ id: 'canon_gushi_tingzhong', title: '庭中有奇树', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['思念', '花树'], popularity: 'classic', difficulty: '入门', source: '通行本（《文选》）', text: '庭中有奇树，绿叶发华滋。攀条折其荣，将以遗所思。\n馨香盈怀袖，路远莫致之。此物何足贵，但感别经时。' }),
  W({ id: 'canon_gushi_tiaotiao', title: '迢迢牵牛星', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['七夕', '思念'], popularity: 'classic', difficulty: '入门', source: '通行本（《文选》）', text: '迢迢牵牛星，皎皎河汉女。纤纤擢素手，札札弄机杼。\n终日不成章，泣涕零如雨。河汉清且浅，相去复几许。\n盈盈一水间，脉脉不得语。' }),
  W({ id: 'canon_gushi_huijia', title: '回车驾言迈', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['人生', '荣名'], popularity: 'normal', difficulty: '深造', source: '通行本（《文选》）', text: '回车驾言迈，悠悠涉长道。四顾何茫茫，东风摇百草。\n所遇无故物，焉得不速老。盛衰各有时，立身苦不早。\n人生非金石，岂能长寿考。奄忽随物化，荣名以为宝。' }),
  W({ id: 'canon_gushi_quche', title: '驱车上东门', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['生死', '人生'], popularity: 'normal', difficulty: '深造', source: '通行本（《文选》）', text: '驱车上东门，遥望郭北墓。白杨何萧萧，松柏夹广路。\n下有陈死人，杳杳即长暮。潜寐黄泉下，千年永不寤。\n浩浩阴阳移，年命如朝露。人生忽如寄，寿无金石固。\n万岁更相送，贤圣莫能度。服食求神仙，多为药所误。\n不如饮美酒，被服纨与素。' }),
  W({ id: 'canon_gushi_quzhe', title: '去者日以疏', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['怀乡', '生死'], popularity: 'normal', difficulty: '进阶', source: '通行本（《文选》）', text: '去者日以疏，来者日以亲。出郭门直视，但见丘与坟。\n古墓犁为田，松柏摧为薪。白杨多悲风，萧萧愁杀人。\n思还故里闾，欲归道无因。' }),
  W({ id: 'canon_gushi_shengnian', title: '生年不满百', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['惜时', '人生'], popularity: 'classic', difficulty: '进阶', source: '通行本（《文选》）', text: '生年不满百，常怀千岁忧。昼短苦夜长，何不秉烛游。\n为乐当及时，何能待来兹。愚者爱惜费，但为后世嗤。\n仙人王子乔，难可与等期。' }),
  W({ id: 'canon_gushi_linlin', title: '凛凛岁云暮（节选）', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['冬夜', '思念'], popularity: 'normal', difficulty: '进阶', source: '通行本（《文选》）', text: '凛凛岁云暮，蝼蛄夕鸣悲。凉风率已厉，游子寒无衣。' }),
  W({ id: 'canon_gushi_mengdong', title: '孟冬寒气至', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['冬夜', '书信'], popularity: 'normal', difficulty: '深造', source: '通行本（《文选》）', text: '孟冬寒气至，北风何惨栗。愁多知夜长，仰观众星列。\n三五明月满，四五蟾兔缺。客从远方来，遗我一书札。\n上言长相思，下言久离别。置书怀袖中，三岁字不灭。\n一心抱区区，惧君不识察。' }),
  W({ id: 'canon_gushi_kecong', title: '客从远方来', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['赠答', '情谊'], popularity: 'normal', difficulty: '进阶', source: '通行本（《文选》）', text: '客从远方来，遗我一端绮。相去万余里，故人心尚尔。\n文彩双鸳鸯，裁为合欢被。著以长相思，缘以结不解。\n以胶投漆中，谁能别离此。' }),
  W({ id: 'canon_gushi_mingyuehe', title: '明月何皎皎', author: '佚名', dynasty: '两汉', genre: '诗', collection: '古诗十九首', tags: ['月夜', '怀乡'], popularity: 'classic', difficulty: '进阶', source: '通行本（《文选》）', text: '明月何皎皎，照我罗床帏。忧愁不能寐，揽衣起徘徊。\n客行虽云乐，不如早旋归。出户独彷徨，愁思当告谁。\n引领还入房，泪下沾裳衣。' }),
  W({ id: 'canon_han_moshang', title: '陌上桑（节选）', author: '汉乐府', dynasty: '两汉', genre: '诗', collection: '乐府诗集', tags: ['民歌', '罗敷'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '日出东南隅，照我秦氏楼。秦氏有好女，自名为罗敷。\n罗敷喜蚕桑，采桑城南隅。青丝为笼系，桂枝为笼钩。' }),
  W({ id: 'canon_han_shiwu', title: '十五从军征', author: '汉乐府', dynasty: '两汉', genre: '诗', collection: '乐府诗集', tags: ['战争', '悲苦'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '十五从军征，八十始得归。道逢乡里人：家中有阿谁？\n遥看是君家，松柏冢累累。兔从狗窦入，雉从梁上飞。\n中庭生旅谷，井上生旅葵。舂谷持作饭，采葵持作羹。\n羹饭一时熟，不知贻阿谁。出门东向看，泪落沾我衣。' }),
  W({ id: 'canon_han_xielu', title: '薤露', author: '汉乐府', dynasty: '两汉', genre: '诗', collection: '乐府诗集', tags: ['生死', '挽歌', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本', text: '薤上露，何易晞。露晞明朝更复落，人死一去何时归。' }),
  W({ id: 'canon_han_haoli', title: '蒿里', author: '汉乐府', dynasty: '两汉', genre: '诗', collection: '乐府诗集', tags: ['生死', '挽歌', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本', text: '蒿里谁家地，聚敛魂魄无贤愚。鬼伯一何相催促，人命不得少踟蹰。' }),

  // ── 魏晋南北朝 ─────────────────────────────────────────────
  W({ id: 'canon_caocao_guancanghai', title: '观沧海', author: '曹操', dynasty: '魏晋南北朝', genre: '诗', collection: '', tags: ['山水', '胸襟'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '东临碣石，以观沧海。水何澹澹，山岛竦峙。\n树木丛生，百草丰茂。秋风萧瑟，洪波涌起。' }),
  W({ id: 'canon_caozhi_qibushi', title: '七步诗', author: '曹植', dynasty: '魏晋南北朝', genre: '诗', collection: '', tags: ['急智', '兄弟'], popularity: 'classic', difficulty: '蒙学', source: '通行本（四句本）', text: '煮豆燃豆萁，豆在釜中泣。本是同根生，相煎何太急？' }),
  W({ id: 'canon_taoyuan_yinjiu', title: '饮酒 · 其五', author: '陶渊明', dynasty: '魏晋南北朝', genre: '诗', collection: '陶渊明集', tags: ['田园', '隐逸'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '结庐在人境，而无车马喧。问君何能尔？心远地自偏。\n采菊东篱下，悠然见南山。山气日夕佳，飞鸟相与还。\n此中有真意，欲辨已忘言。' }),
  W({ id: 'canon_taoyuan_guiyuan3', title: '归园田居 · 其三', author: '陶渊明', dynasty: '魏晋南北朝', genre: '诗', collection: '陶渊明集', tags: ['田园', '劳作'], popularity: 'normal', difficulty: '入门', source: '通行本', text: '种豆南山下，草盛豆苗稀。晨兴理荒秽，带月荷锄归。\n道狭草木长，夕露沾我衣。衣沾不足惜，但使愿无违。' }),
  W({ id: 'canon_chilege', title: '敕勒歌', author: '佚名（北朝民歌）', dynasty: '魏晋南北朝', genre: '诗', collection: '乐府诗集', tags: ['草原', '民歌'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '敕勒川，阴山下。天似穹庐，笼盖四野。\n天苍苍，野茫茫，风吹草低见牛羊。' }),
  W({ id: 'canon_caocao_guisuishou', title: '龟虽寿', author: '曹操', dynasty: '魏晋南北朝', genre: '诗', collection: '', tags: ['壮心', '哲理'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '神龟虽寿，犹有竟时。腾蛇乘雾，终为土灰。\n老骥伏枥，志在千里。烈士暮年，壮心不已。\n盈缩之期，不但在天。养怡之福，可得永年。\n幸甚至哉，歌以咏志。' }),
  W({ id: 'canon_caocao_duangexing', title: '短歌行（节选）', author: '曹操', dynasty: '魏晋南北朝', genre: '诗', collection: '', tags: ['求贤', '感慨'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '对酒当歌，人生几何！譬如朝露，去日苦多。\n慨当以慷，忧思难忘。何以解忧？唯有杜康。\n月明星稀，乌鹊南飞。绕树三匝，何枝可依？\n山不厌高，海不厌深。周公吐哺，天下归心。' }),
  W({ id: 'canon_taoyuan_guiyuan1', title: '归园田居 · 其一', author: '陶渊明', dynasty: '魏晋南北朝', genre: '诗', collection: '陶渊明集', tags: ['田园', '隐逸'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '少无适俗韵，性本爱丘山。误落尘网中，一去三十年。\n羁鸟恋旧林，池鱼思故渊。开荒南野际，守拙归园田。\n方宅十余亩，草屋八九间。榆柳荫后檐，桃李罗堂前。\n暧暧远人村，依依墟里烟。狗吠深巷中，鸡鸣桑树颠。\n户庭无尘杂，虚室有余闲。久在樊笼里，复得返自然。' }),
  W({ id: 'canon_taoyuan_taohuayuanji', title: '桃花源记（节选）', author: '陶渊明', dynasty: '魏晋南北朝', genre: '文', collection: '陶渊明集', tags: ['乌托邦', '叙事'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '晋太元中，武陵人捕鱼为业。缘溪行，忘路之远近。忽逢桃花林，夹岸数百步，中无杂树，芳草鲜美，落英缤纷。\n土地平旷，屋舍俨然，有良田、美池、桑竹之属。阡陌交通，鸡犬相闻。' }),
  W({ id: 'canon_mulanshi', title: '木兰诗（节选）', author: '佚名（北朝民歌）', dynasty: '魏晋南北朝', genre: '诗', collection: '乐府诗集', tags: ['英雄', '民歌'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '唧唧复唧唧，木兰当户织。不闻机杼声，唯闻女叹息。\n问女何所思，问女何所忆。女亦无所思，女亦无所忆。昨夜见军帖，可汗大点兵，军书十二卷，卷卷有爷名。阿爷无大儿，木兰无长兄，愿为市鞍马，从此替爷征。\n万里赴戎机，关山度若飞。朔气传金柝，寒光照铁衣。将军百战死，壮士十年归。\n雄兔脚扑朔，雌兔眼迷离。双兔傍地走，安能辨我是雄雌？' }),
  W({ id: 'canon_xizhouqu', title: '西洲曲（节选）', author: '佚名（南朝民歌）', dynasty: '魏晋南北朝', genre: '诗', collection: '乐府诗集', tags: ['采莲', '相思', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本（《玉台新咏》）', text: '忆梅下西洲，折梅寄江北。西洲在何处？两桨桥头渡。\n日暮伯劳飞，风吹乌臼树。树下即门前，门中露翠钿。' }),
  W({ id: 'canon_shuijingzhu_sanxia', title: '水经注 · 三峡（节选）', author: '郦道元', dynasty: '魏晋南北朝', genre: '文', collection: '', tags: ['山水', '地理'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '自三峡七百里中，两岸连山，略无阙处。重岩叠嶂，隐天蔽日，自非亭午夜分，不见曦月。\n春冬之时，则素湍绿潭，回清倒影。绝巘多生怪柏，悬泉瀑布，飞漱其间。清荣峻茂，良多趣味。\n每至晴初霜旦，林寒涧肃，常有高猿长啸，属引凄异，空谷传响，哀转久绝。故渔者歌曰：巴东三峡巫峡长，猿鸣三声泪沾裳。' }),
  W({ id: 'canon_qianziwen', title: '千字文（节选）', author: '周兴嗣', dynasty: '魏晋南北朝', genre: '蒙学', collection: '千字文', tags: ['蒙学', '识字'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '天地玄黄，宇宙洪荒。日月盈昃，辰宿列张。\n寒来暑往，秋收冬藏。闰余成岁，律吕调阳。' }),
  W({ id: 'canon_lantingxu', title: '兰亭集序（节选）', author: '王羲之', dynasty: '魏晋南北朝', genre: '文', collection: '', tags: ['雅集', '人生'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。群贤毕至，少长咸集。此地有崇山峻岭，茂林修竹，又有清流激湍，映带左右。\n是日也，天朗气清，惠风和畅。仰观宇宙之大，俯察品类之盛，所以游目骋怀，足以极视听之娱，信可乐也。' }),

  // ── 唐 ─────────────────────────────────────────────────────
  W({ id: 'canon_tang_yonge', title: '咏鹅', author: '骆宾王', dynasty: '唐', genre: '诗', collection: '', tags: ['启蒙', '状物'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '鹅，鹅，鹅，曲项向天歌。白毛浮绿水，红掌拨清波。' }),
  W({ id: 'canon_tang_huixiangou', title: '回乡偶书', author: '贺知章', dynasty: '唐', genre: '诗', collection: '', tags: ['乡情', '岁月'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '少小离家老大回，乡音无改鬓毛衰。\n儿童相见不相识，笑问客从何处来。' }),
  W({ id: 'canon_tang_dengguanquelou', title: '登鹳雀楼', author: '王之涣', dynasty: '唐', genre: '诗', collection: '', tags: ['写景', '哲理', '对仗'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '白日依山尽，黄河入海流。欲穷千里目，更上一层楼。' }),
  W({ id: 'canon_tang_jingyesi', title: '静夜思', author: '李白', dynasty: '唐', genre: '诗', collection: '', tags: ['思乡', '月亮'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '床前明月光，疑是地上霜。举头望明月，低头思故乡。' }),
  W({ id: 'canon_tang_chunxiao', title: '春晓', author: '孟浩然', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['春天', '晨景'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '春眠不觉晓，处处闻啼鸟。夜来风雨声，花落知多少。' }),
  W({ id: 'canon_tang_luzhai', title: '鹿柴', author: '王维', dynasty: '唐', genre: '诗', collection: '', tags: ['山居', '空静'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '空山不见人，但闻人语响。返景入深林，复照青苔上。' }),
  W({ id: 'canon_tang_lushanpubu', title: '望庐山瀑布', author: '李白', dynasty: '唐', genre: '诗', collection: '', tags: ['山水', '夸张'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '日照香炉生紫烟，遥看瀑布挂前川。\n飞流直下三千尺，疑是银河落九天。' }),
  W({ id: 'canon_tang_zaofabaidicheng', title: '早发白帝城', author: '李白', dynasty: '唐', genre: '诗', collection: '', tags: ['行旅', '轻快'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '朝辞白帝彩云间，千里江陵一日还。\n两岸猿声啼不住，轻舟已过万重山。' }),
  W({ id: 'canon_tang_fengqiaoyebo', title: '枫桥夜泊', author: '张继', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['羁旅', '钟声'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '月落乌啼霜满天，江枫渔火对愁眠。\n姑苏城外寒山寺，夜半钟声到客船。' }),
  W({ id: 'canon_tang_xunyinzhe', title: '寻隐者不遇', author: '贾岛', dynasty: '唐', genre: '诗', collection: '', tags: ['访友', '问答', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '松下问童子，言师采药去。\n只在此山中，云深不知处。' }),
  W({ id: 'canon_tang_jiangxue', title: '江雪', author: '柳宗元', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['孤高', '冬雪'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '千山鸟飞绝，万径人踪灭。孤舟蓑笠翁，独钓寒江雪。' }),
  W({ id: 'canon_tang_minnong', title: '悯农 · 其二', author: '李绅', dynasty: '唐', genre: '诗', collection: '', tags: ['悯农', '惜物'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦。' }),
  W({ id: 'canon_tang_shanxing', title: '山行', author: '杜牧', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['秋天', '红叶'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '远上寒山石径斜，白云生处有人家。\n停车坐爱枫林晚，霜叶红于二月花。' }),
  W({ id: 'canon_tang_qingming', title: '清明', author: '杜牧', dynasty: '唐', genre: '诗', collection: '', tags: ['节令', '行旅'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '清明时节雨纷纷，路上行人欲断魂。\n借问酒家何处有？牧童遥指杏花村。' }),
  W({ id: 'canon_tang_yongliu', title: '咏柳', author: '贺知章', dynasty: '唐', genre: '诗', collection: '', tags: ['春天', '状物'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '碧玉妆成一树高，万条垂下绿丝绦。\n不知细叶谁裁出，二月春风似剪刀。' }),
  W({ id: 'canon_tang_huixiang2', title: '回乡偶书 · 其二', author: '贺知章', dynasty: '唐', genre: '诗', collection: '', tags: ['乡情', '岁月', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '离别家乡岁月多，近来人事半消磨。\n惟有门前镜湖水，春风不改旧时波。' }),
  W({ id: 'canon_tang_dengyouzhou', title: '登幽州台歌', author: '陈子昂', dynasty: '唐', genre: '诗', collection: '', tags: ['怀才', '天地'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '前不见古人，后不见来者。念天地之悠悠，独怆然而涕下！' }),
  W({ id: 'canon_tang_songdushaofu', title: '送杜少府之任蜀州', author: '王勃', dynasty: '唐', genre: '诗', collection: '', tags: ['送别', '名句'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '城阙辅三秦，风烟望五津。与君离别意，同是宦游人。\n海内存知己，天涯若比邻。无为在歧路，儿女共沾巾。' }),
  W({ id: 'canon_tang_wangyuehuaiyuan', title: '望月怀远（节选）', author: '张九龄', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['月亮', '相思'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '海上生明月，天涯共此时。情人怨遥夜，竟夕起相思。' }),
  W({ id: 'canon_tang_liangzhou_wang', title: '凉州词', author: '王之涣', dynasty: '唐', genre: '诗', collection: '', tags: ['边塞', '苍凉'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '黄河远上白云间，一片孤城万仞山。\n羌笛何须怨杨柳，春风不度玉门关。' }),
  W({ id: 'canon_tang_xiangsi', title: '相思', author: '王维', dynasty: '唐', genre: '诗', collection: '', tags: ['红豆', '情谊'], popularity: 'normal', difficulty: '蒙学', source: '通行本', text: '红豆生南国，春来发几枝。愿君多采撷，此物最相思。' }),
  W({ id: 'canon_tang_zhuliguan', title: '竹里馆', author: '王维', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['山居', '空静'], popularity: 'normal', difficulty: '入门', source: '通行本', text: '独坐幽篁里，弹琴复长啸。深林人不知，明月来相照。' }),
  W({ id: 'canon_tang_niaomingjian', title: '鸟鸣涧', author: '王维', dynasty: '唐', genre: '诗', collection: '', tags: ['春山', '空静'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '人闲桂花落，夜静春山空。月出惊山鸟，时鸣春涧中。' }),
  W({ id: 'canon_tang_jiuyuejiu', title: '九月九日忆山东兄弟', author: '王维', dynasty: '唐', genre: '诗', collection: '', tags: ['重阳', '思乡'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '独在异乡为异客，每逢佳节倍思亲。\n遥知兄弟登高处，遍插茱萸少一人。' }),
  W({ id: 'canon_tang_songyuaner', title: '送元二使安西', author: '王维', dynasty: '唐', genre: '诗', collection: '', tags: ['送别', '杨柳'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '渭城朝雨浥轻尘，客舍青青柳色新。\n劝君更尽一杯酒，西出阳关无故人。' }),
  W({ id: 'canon_tang_shizhisai', title: '使至塞上', author: '王维', dynasty: '唐', genre: '诗', collection: '', tags: ['边塞', '名句'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '单车欲问边，属国过居延。征蓬出汉塞，归雁入胡天。\n大漠孤烟直，长河落日圆。萧关逢候骑，都护在燕然。' }),
  W({ id: 'canon_tang_chusai', title: '出塞', author: '王昌龄', dynasty: '唐', genre: '诗', collection: '', tags: ['边塞', '明月'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '秦时明月汉时关，万里长征人未还。\n但使龙城飞将在，不教胡马度阴山。' }),
  W({ id: 'canon_tang_furonglou', title: '芙蓉楼送辛渐', author: '王昌龄', dynasty: '唐', genre: '诗', collection: '', tags: ['送别', '品格'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '寒雨连江夜入吴，平明送客楚山孤。\n洛阳亲友如相问，一片冰心在玉壶。' }),
  W({ id: 'canon_tang_liangzhou_wanghan', title: '凉州词', author: '王翰', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['边塞', '宴饮'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '葡萄美酒夜光杯，欲饮琵琶马上催。\n醉卧沙场君莫笑，古来征战几人回？' }),
  W({ id: 'canon_tang_biedongda', title: '别董大', author: '高适', dynasty: '唐', genre: '诗', collection: '', tags: ['送别', '豪迈'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '千里黄云白日曛，北风吹雁雪纷纷。\n莫愁前路无知己，天下谁人不识君。' }),
  W({ id: 'canon_tang_fengrujing', title: '逢入京使', author: '岑参', dynasty: '唐', genre: '诗', collection: '', tags: ['思乡', '口信', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '故园东望路漫漫，双袖龙钟泪不干。\n马上相逢无纸笔，凭君传语报平安。' }),
  W({ id: 'canon_tang_baixuege', title: '白雪歌送武判官归京（节选）', author: '岑参', dynasty: '唐', genre: '诗', collection: '', tags: ['边塞', '雪'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '北风卷地白草折，胡天八月即飞雪。忽如一夜春风来，千树万树梨花开。\n散入珠帘湿罗幕，狐裘不暖锦衾薄。' }),
  W({ id: 'canon_tang_yanmen', title: '雁门太守行', author: '李贺', dynasty: '唐', genre: '诗', collection: '', tags: ['边塞', '悲壮'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '黑云压城城欲摧，甲光向日金鳞开。角声满天秋色里，塞上燕脂凝夜紫。\n半卷红旗临易水，霜重鼓寒声不起。报君黄金台上意，提携玉龙为君死。' }),
  W({ id: 'canon_tang_mashi', title: '马诗 · 其五', author: '李贺', dynasty: '唐', genre: '诗', collection: '', tags: ['咏物', '志向'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '大漠沙如雪，燕山月似钩。何当金络脑，快走踏清秋。' }),
  W({ id: 'canon_tang_huanghelou', title: '黄鹤楼', author: '崔颢', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['登楼', '乡愁'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '昔人已乘黄鹤去，此地空余黄鹤楼。黄鹤一去不复返，白云千载空悠悠。\n晴川历历汉阳树，芳草萋萋鹦鹉洲。日暮乡关何处是？烟波江上使人愁。' }),
  W({ id: 'canon_tang_chunyexiyu', title: '春夜喜雨', author: '杜甫', dynasty: '唐', genre: '诗', collection: '', tags: ['春天', '喜雨'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '好雨知时节，当春乃发生。随风潜入夜，润物细无声。\n野径云俱黑，江船火独明。晓看红湿处，花重锦官城。' }),
  W({ id: 'canon_tang_jueju_huangli', title: '绝句（两个黄鹂）', author: '杜甫', dynasty: '唐', genre: '诗', collection: '', tags: ['春天', '对仗'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '两个黄鹂鸣翠柳，一行白鹭上青天。\n窗含西岭千秋雪，门泊东吴万里船。' }),
  W({ id: 'canon_tang_chunwang', title: '春望', author: '杜甫', dynasty: '唐', genre: '诗', collection: '', tags: ['战乱', '家国'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '国破山河在，城春草木深。感时花溅泪，恨别鸟惊心。\n烽火连三月，家书抵万金。白头搔更短，浑欲不胜簪。' }),
  W({ id: 'canon_tang_wangyue', title: '望岳', author: '杜甫', dynasty: '唐', genre: '诗', collection: '', tags: ['泰山', '壮志'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '岱宗夫如何？齐鲁青未了。造化钟神秀，阴阳割昏晓。\n荡胸生曾云，决眦入归鸟。会当凌绝顶，一览众山小。' }),
  W({ id: 'canon_tang_wenguanjun', title: '闻官军收河南河北', author: '杜甫', dynasty: '唐', genre: '诗', collection: '', tags: ['狂喜', '还乡'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '剑外忽传收蓟北，初闻涕泪满衣裳。却看妻子愁何在，漫卷诗书喜欲狂。\n白日放歌须纵酒，青春作伴好还乡。即从巴峡穿巫峡，便下襄阳向洛阳。' }),
  W({ id: 'canon_tang_zenghuaqing', title: '赠花卿', author: '杜甫', dynasty: '唐', genre: '诗', collection: '', tags: ['音乐', '讽喻', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '锦城丝管日纷纷，半入江风半入云。\n此曲只应天上有，人间能得几回闻。' }),
  W({ id: 'canon_tang_jiangpan', title: '江畔独步寻花 · 其六', author: '杜甫', dynasty: '唐', genre: '诗', collection: '', tags: ['春花', '闲趣'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '黄四娘家花满蹊，千朵万朵压枝低。\n留连戏蝶时时舞，自在娇莺恰恰啼。' }),
  W({ id: 'canon_tang_wangtianshan', title: '望天门山', author: '李白', dynasty: '唐', genre: '诗', collection: '', tags: ['山水', '豪放'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '天门中断楚江开，碧水东流至此回。\n两岸青山相对出，孤帆一片日边来。' }),
  W({ id: 'canon_tang_songmenghaoran', title: '黄鹤楼送孟浩然之广陵', author: '李白', dynasty: '唐', genre: '诗', collection: '', tags: ['送别', '烟花'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '故人西辞黄鹤楼，烟花三月下扬州。\n孤帆远影碧空尽，唯见长江天际流。' }),
  W({ id: 'canon_tang_zengwanglun', title: '赠汪伦', author: '李白', dynasty: '唐', genre: '诗', collection: '', tags: ['送别', '情谊'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '李白乘舟将欲行，忽闻岸上踏歌声。\n桃花潭水深千尺，不及汪伦送我情。' }),
  W({ id: 'canon_tang_duzuo', title: '独坐敬亭山', author: '李白', dynasty: '唐', genre: '诗', collection: '', tags: ['孤独', '山'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '众鸟高飞尽，孤云独去闲。相看两不厌，只有敬亭山。' }),
  W({ id: 'canon_tang_yuexiaduzhuo', title: '月下独酌（节选）', author: '李白', dynasty: '唐', genre: '诗', collection: '', tags: ['月亮', '孤独', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '花间一壶酒，独酌无相亲。举杯邀明月，对影成三人。' }),
  W({ id: 'canon_tang_kezhongxing', title: '客中行', author: '李白', dynasty: '唐', genre: '诗', collection: '', tags: ['行旅', '酒', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '兰陵美酒郁金香，玉碗盛来琥珀光。\n但使主人能醉客，不知何处是他乡。' }),
  W({ id: 'canon_tang_youziyin', title: '游子吟', author: '孟郊', dynasty: '唐', genre: '诗', collection: '', tags: ['母爱', '亲情'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '慈母手中线，游子身上衣。临行密密缝，意恐迟迟归。\n谁言寸草心，报得三春晖。' }),
  W({ id: 'canon_tang_dengkehou', title: '登科后', author: '孟郊', dynasty: '唐', genre: '诗', collection: '', tags: ['春风得意', '名句', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '昔日龌龊不足夸，今朝放荡思无涯。\n春风得意马蹄疾，一日看尽长安花。' }),
  W({ id: 'canon_tang_sujiandeguan', title: '宿建德江', author: '孟浩然', dynasty: '唐', genre: '诗', collection: '', tags: ['羁旅', '江月'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '移舟泊烟渚，日暮客愁新。野旷天低树，江清月近人。' }),
  W({ id: 'canon_tang_guogurenzhuang', title: '过故人庄', author: '孟浩然', dynasty: '唐', genre: '诗', collection: '', tags: ['田园', '友情'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '故人具鸡黍，邀我至田家。绿树村边合，青山郭外斜。\n开轩面场圃，把酒话桑麻。待到重阳日，还来就菊花。' }),
  W({ id: 'canon_tang_zaocheng', title: '早春呈水部张十八员外', author: '韩愈', dynasty: '唐', genre: '诗', collection: '', tags: ['早春', '草色'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '天街小雨润如酥，草色遥看近却无。\n最是一年春好处，绝胜烟柳满皇都。' }),
  W({ id: 'canon_tang_wanchun', title: '晚春', author: '韩愈', dynasty: '唐', genre: '诗', collection: '', tags: ['春天', '杨花', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '草树知春不久归，百般红紫斗芳菲。\n杨花榆荚无才思，惟解漫天作雪飞。' }),
  W({ id: 'canon_tang_yuweng', title: '渔翁', author: '柳宗元', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['山水', '隐逸', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本', text: '渔翁夜傍西岩宿，晓汲清湘燃楚竹。\n烟销日出不见人，欸乃一声山水绿。\n回看天际下中流，岩上无心云相逐。' }),
  W({ id: 'canon_tang_tilining', title: '题李凝幽居（节选）', author: '贾岛', dynasty: '唐', genre: '诗', collection: '', tags: ['推敲', '月夜', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '闲居少邻并，草径入荒园。鸟宿池边树，僧敲月下门。' }),
  W({ id: 'canon_tang_yejiyubei', title: '夜雨寄北', author: '李商隐', dynasty: '唐', genre: '诗', collection: '', tags: ['思念', '巴山'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '君问归期未有期，巴山夜雨涨秋池。\n何当共剪西窗烛，却话巴山夜雨时。' }),
  W({ id: 'canon_tang_wuti_xiangjian', title: '无题 · 相见时难（节选）', author: '李商隐', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['爱情', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '相见时难别亦难，东风无力百花残。春蚕到死丝方尽，蜡炬成灰泪始干。' }),
  W({ id: 'canon_tang_dengleyouyuan', title: '登乐游原', author: '李商隐', dynasty: '唐', genre: '诗', collection: '', tags: ['黄昏', '名句'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '向晚意不适，驱车登古原。夕阳无限好，只是近黄昏。' }),
  W({ id: 'canon_tang_change', title: '嫦娥', author: '李商隐', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['月亮', '孤寂', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '云母屏风烛影深，长河渐落晓星沉。\n嫦娥应悔偷灵药，碧海青天夜夜心。' }),
  W({ id: 'canon_tang_boqinhuai', title: '泊秦淮', author: '杜牧', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['咏史', '烟月'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '烟笼寒水月笼沙，夜泊秦淮近酒家。\n商女不知亡国恨，隔江犹唱后庭花。' }),
  W({ id: 'canon_tang_jiangnanchun', title: '江南春', author: '杜牧', dynasty: '唐', genre: '诗', collection: '', tags: ['春天', '写景'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '千里莺啼绿映红，水村山郭酒旗风。\n南朝四百八十寺，多少楼台烟雨中。' }),
  W({ id: 'canon_tang_chibi', title: '赤壁', author: '杜牧', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['咏史', '东风'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '折戟沉沙铁未销，自将磨洗认前朝。\n东风不与周郎便，铜雀春深锁二乔。' }),
  W({ id: 'canon_tang_hanchuo', title: '寄扬州韩绰判官', author: '杜牧', dynasty: '唐', genre: '诗', collection: '', tags: ['江南', '明月', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '青山隐隐水迢迢，秋尽江南草未凋。\n二十四桥明月夜，玉人何处教吹箫。' }),
  W({ id: 'canon_tang_wangdongting', title: '望洞庭', author: '刘禹锡', dynasty: '唐', genre: '诗', collection: '', tags: ['秋月', '湖光'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '湖光秋月两相和，潭面无风镜未磨。\n遥望洞庭山水翠，白银盘里一青螺。' }),
  W({ id: 'canon_tang_langtaosha', title: '浪淘沙 · 其一', author: '刘禹锡', dynasty: '唐', genre: '诗', collection: '', tags: ['黄河', '豪迈'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '九曲黄河万里沙，浪淘风簸自天涯。\n如今直上银河去，同到牵牛织女家。' }),
  W({ id: 'canon_tang_wuyixiang', title: '乌衣巷', author: '刘禹锡', dynasty: '唐', genre: '诗', collection: '', tags: ['咏史', '兴亡'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '朱雀桥边野草花，乌衣巷口夕阳斜。\n旧时王谢堂前燕，飞入寻常百姓家。' }),
  W({ id: 'canon_tang_zhuzhici', title: '竹枝词 · 其一', author: '刘禹锡', dynasty: '唐', genre: '诗', collection: '', tags: ['民歌', '爱情'], popularity: 'normal', difficulty: '入门', source: '通行本', text: '杨柳青青江水平，闻郎江上踏歌声。\n东边日出西边雨，道是无晴却有晴。' }),
  W({ id: 'canon_tang_chouletian', title: '酬乐天扬州初逢席上见赠', author: '刘禹锡', dynasty: '唐', genre: '诗', collection: '', tags: ['赠答', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '巴山楚水凄凉地，二十三年弃置身。怀旧空吟闻笛赋，到乡翻似烂柯人。\n沉舟侧畔千帆过，病树前头万木春。今日听君歌一曲，暂凭杯酒长精神。' }),
  W({ id: 'canon_tang_fudecao', title: '赋得古原草送别（节选）', author: '白居易', dynasty: '唐', genre: '诗', collection: '', tags: ['春草', '送别'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '离离原上草，一岁一枯荣。野火烧不尽，春风吹又生。' }),
  W({ id: 'canon_tang_yijiangnan', title: '忆江南', author: '白居易', dynasty: '唐', genre: '词', collection: '', tags: ['江南', '回忆'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '江南好，风景旧曾谙。日出江花红胜火，春来江水绿如蓝。能不忆江南？' }),
  W({ id: 'canon_tang_qiantanghu', title: '钱塘湖春行', author: '白居易', dynasty: '唐', genre: '诗', collection: '', tags: ['西湖', '早春'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '孤山寺北贾亭西，水面初平云脚低。几处早莺争暖树，谁家新燕啄春泥。\n乱花渐欲迷人眼，浅草才能没马蹄。最爱湖东行不足，绿杨阴里白沙堤。' }),
  W({ id: 'canon_tang_mujiangyin', title: '暮江吟', author: '白居易', dynasty: '唐', genre: '诗', collection: '', tags: ['秋夜', '残阳'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '一道残阳铺水中，半江瑟瑟半江红。可怜九月初三夜，露似真珠月似弓。' }),
  W({ id: 'canon_tang_wenliushijiu', title: '问刘十九', author: '白居易', dynasty: '唐', genre: '诗', collection: '', tags: ['雪夜', '酒', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '绿蚁新醅酒，红泥小火炉。晚来天欲雪，能饮一杯无？' }),
  W({ id: 'canon_tang_chunyuan', title: '春怨', author: '金昌绪', dynasty: '唐', genre: '诗', collection: '', tags: ['闺怨', '黄莺', '冷门佳作'], popularity: 'notable', difficulty: '蒙学', source: '通行本（《全唐诗》）', text: '打起黄莺儿，莫教枝上啼。啼时惊妾梦，不得到辽西。' }),
  W({ id: 'canon_tang_yueye', title: '月夜', author: '刘方平', dynasty: '唐', genre: '诗', collection: '', tags: ['春夜', '虫声', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《全唐诗》）', text: '更深月色半人家，北斗阑干南斗斜。今夜偏知春气暖，虫声新透绿窗纱。' }),
  W({ id: 'canon_tang_taohuaxi', title: '桃花溪', author: '张旭', dynasty: '唐', genre: '诗', collection: '', tags: ['桃花', '问津', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《全唐诗》）', text: '隐隐飞桥隔野烟，石矶西畔问渔船。桃花尽日随流水，洞在清溪何处边。' }),
  W({ id: 'canon_tang_qiuyejiqu', title: '秋夜寄丘员外', author: '韦应物', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['秋夜', '怀友', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '怀君属秋夜，散步咏凉天。空山松子落，幽人应未眠。' }),
  W({ id: 'canon_tang_chuzhouxijian', title: '滁州西涧', author: '韦应物', dynasty: '唐', genre: '诗', collection: '', tags: ['幽草', '野渡'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '独怜幽草涧边生，上有黄鹂深树鸣。春潮带雨晚来急，野渡无人舟自横。' }),
  W({ id: 'canon_tang_fengxue', title: '逢雪宿芙蓉山主人', author: '刘长卿', dynasty: '唐', genre: '诗', collection: '', tags: ['风雪', '夜归'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '日暮苍山远，天寒白屋贫。柴门闻犬吠，风雪夜归人。' }),
  W({ id: 'canon_tang_songlingche', title: '送灵澈上人', author: '刘长卿', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['送别', '青山', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '苍苍竹林寺，杳杳钟声晚。荷笠带斜阳，青山独归远。' }),
  W({ id: 'canon_tang_jiangcun', title: '江村即事', author: '司空曙', dynasty: '唐', genre: '诗', collection: '', tags: ['钓罢', '芦花', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《全唐诗》）', text: '钓罢归来不系船，江村月落正堪眠。纵然一夜风吹去，只在芦花浅水边。' }),
  W({ id: 'canon_tang_yeshangshouxiang', title: '夜上受降城闻笛', author: '李益', dynasty: '唐', genre: '诗', collection: '', tags: ['边塞', '芦笛', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《全唐诗》）', text: '回乐峰前沙似雪，受降城外月如霜。不知何处吹芦管，一夜征人尽望乡。' }),
  W({ id: 'canon_tang_jiangnanqu', title: '江南曲', author: '李益', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['闺怨', '潮信', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '嫁得瞿塘贾，朝朝误妾期。早知潮有信，嫁与弄潮儿。' }),
  W({ id: 'canon_tang_saixia2', title: '塞下曲 · 其二', author: '卢纶', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['边塞', '射虎', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '林暗草惊风，将军夜引弓。平明寻白羽，没在石棱中。' }),
  W({ id: 'canon_tang_saixia3', title: '塞下曲 · 其三', author: '卢纶', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['边塞', '大雪'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '月黑雁飞高，单于夜遁逃。欲将轻骑逐，大雪满弓刀。' }),
  W({ id: 'canon_tang_shiwuwangyue', title: '十五夜望月', author: '王建', dynasty: '唐', genre: '诗', collection: '', tags: ['中秋', '秋思', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《全唐诗》）', text: '中庭地白树栖鸦，冷露无声湿桂花。今夜月明人尽望，不知秋思落谁家。' }),
  W({ id: 'canon_tang_gongci', title: '宫词', author: '张祜', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['宫怨', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '故国三千里，深宫二十年。一声何满子，双泪落君前。' }),
  W({ id: 'canon_tang_jinshi', title: '近试上张水部', author: '朱庆馀', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['喻诗', '画眉', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '洞房昨夜停红烛，待晓堂前拜舅姑。妆罢低声问夫婿，画眉深浅入时无。' }),
  W({ id: 'canon_tang_zhongnanwang', title: '终南望余雪', author: '祖咏', dynasty: '唐', genre: '诗', collection: '唐诗三百首', tags: ['雪', '暮寒', '冷门佳作'], popularity: 'notable', difficulty: '蒙学', source: '通行本', text: '终南阴岭秀，积雪浮云端。林表明霁色，城中增暮寒。' }),
  W({ id: 'canon_tang_tiduchengnanzhuang', title: '题都城南庄', author: '崔护', dynasty: '唐', genre: '诗', collection: '', tags: ['桃花', '人面', '冷门佳作'], popularity: 'notable', difficulty: '蒙学', source: '通行本（《全唐诗》）', text: '去年今日此门中，人面桃花相映红。人面不知何处去，桃花依旧笑春风。' }),
  W({ id: 'canon_tang_longxixing', title: '陇西行 · 其四', author: '陈陶', dynasty: '唐', genre: '诗', collection: '', tags: ['边塞', '悲悯', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本（《全唐诗》）', text: '誓扫匈奴不顾身，五千貂锦丧胡尘。可怜无定河边骨，犹是春闺梦里人。' }),
  W({ id: 'canon_tang_lisi', title: '离思 · 其四', author: '元稹', dynasty: '唐', genre: '诗', collection: '', tags: ['爱情', '名句'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '曾经沧海难为水，除却巫山不是云。取次花丛懒回顾，半缘修道半缘君。' }),
  W({ id: 'canon_tang_juhua', title: '菊花', author: '元稹', dynasty: '唐', genre: '诗', collection: '', tags: ['秋菊', '爱菊', '冷门佳作'], popularity: 'notable', difficulty: '蒙学', source: '通行本（《全唐诗》）', text: '秋丛绕舍似陶家，遍绕篱边日渐斜。不是花中偏爱菊，此花开尽更无花。' }),
  W({ id: 'canon_tang_feng', title: '蜂', author: '罗隐', dynasty: '唐', genre: '诗', collection: '', tags: ['咏物', '勤劳'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '不论平地与山尖，无限风光尽被占。采得百花成蜜后，为谁辛苦为谁甜。' }),
  W({ id: 'canon_tang_shanzaoxing', title: '商山早行', author: '温庭筠', dynasty: '唐', genre: '诗', collection: '', tags: ['羁旅', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '晨起动征铎，客行悲故乡。鸡声茅店月，人迹板桥霜。\n槲叶落山路，枳花明驿墙。因思杜陵梦，凫雁满回塘。' }),
  W({ id: 'canon_tang_pusaman_xiaoshan', title: '菩萨蛮 · 小山重叠金明灭', author: '温庭筠', dynasty: '唐', genre: '词', collection: '花间集', tags: ['闺情', '词祖', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本（《花间集》）', text: '小山重叠金明灭，鬓云欲度香腮雪。懒起画蛾眉，弄妆梳洗迟。\n照花前后镜，花面交相映。新帖绣罗襦，双双金鹧鸪。' }),
  W({ id: 'canon_tang_wangjiangnan', title: '望江南 · 梳洗罢', author: '温庭筠', dynasty: '唐', genre: '词', collection: '花间集', tags: ['望江', '肠断', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《花间集》）', text: '梳洗罢，独倚望江楼。过尽千帆皆不是，斜晖脉脉水悠悠。肠断白蘋洲。' }),

  // ── 五代 ───────────────────────────────────────────────────
  W({ id: 'canon_wudai_yumeiren', title: '虞美人 · 春花秋月何时了', author: '李煜', dynasty: '五代', genre: '词', collection: '南唐二主词', tags: ['亡国之痛', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '春花秋月何时了？往事知多少。小楼昨夜又东风，故国不堪回首月明中。\n雕栏玉砌应犹在，只是朱颜改。问君能有几多愁？恰似一江春水向东流。' }),
  W({ id: 'canon_wudai_pusaman', title: '菩萨蛮 · 其二（人人尽说江南好）', author: '韦庄', dynasty: '五代', genre: '词', collection: '花间集', tags: ['江南', '乡愁', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本', text: '人人尽说江南好，游人只合江南老。春水碧于天，画船听雨眠。\n垆边人似月，皓腕凝霜雪。未老莫还乡，还乡须断肠。' }),
  W({ id: 'canon_wudai_pusaman1', title: '菩萨蛮 · 其一（红楼别夜堪惆怅）', author: '韦庄', dynasty: '五代', genre: '词', collection: '花间集', tags: ['离别', '琵琶', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本（《花间集》）', text: '红楼别夜堪惆怅，香灯半卷流苏帐。残月出门时，美人和泪辞。\n琵琶金翠羽，弦上黄莺语。劝我早还家，绿窗人似花。' }),
  W({ id: 'canon_wudai_xiangjian_wuyan', title: '相见欢 · 无言独上西楼', author: '李煜', dynasty: '五代', genre: '词', collection: '南唐二主词', tags: ['离愁', '名句'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '无言独上西楼，月如钩。寂寞梧桐深院锁清秋。\n剪不断，理还乱，是离愁。别是一般滋味在心头。' }),
  W({ id: 'canon_wudai_xiangjian_linhua', title: '相见欢 · 林花谢了春红', author: '李煜', dynasty: '五代', genre: '词', collection: '南唐二主词', tags: ['惜春', '人生'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '林花谢了春红，太匆匆。无奈朝来寒雨晚来风。\n胭脂泪，相留醉，几时重。自是人生长恨水长东。' }),
  W({ id: 'canon_wudai_langtaosha', title: '浪淘沙令 · 帘外雨潺潺', author: '李煜', dynasty: '五代', genre: '词', collection: '南唐二主词', tags: ['亡国之痛', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '帘外雨潺潺，春意阑珊。罗衾不耐五更寒。梦里不知身是客，一晌贪欢。\n独自莫凭栏，无限江山，别时容易见时难。流水落花春去也，天上人间。' }),
  W({ id: 'canon_wudai_pozhenzi', title: '破阵子 · 四十年来家国', author: '李煜', dynasty: '五代', genre: '词', collection: '南唐二主词', tags: ['亡国之痛', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本（《南唐二主词》）', text: '四十年来家国，三千里地山河。凤阁龙楼连霄汉，玉树琼枝作烟萝，几曾识干戈？\n一旦归为臣虏，沈腰潘鬓消磨。最是仓皇辞庙日，教坊犹奏别离歌，垂泪对宫娥。' }),
  W({ id: 'canon_wudai_yejinmen', title: '谒金门 · 风乍起', author: '冯延巳', dynasty: '五代', genre: '词', collection: '阳春集', tags: ['春水', '闺情', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《阳春集》）', text: '风乍起，吹皱一池春水。闲引鸳鸯香径里，手挼红杏蕊。\n斗鸭阑干独倚，碧玉搔头斜坠。终日望君君不至，举头闻鹊喜。' }),
  W({ id: 'canon_wudai_changmingnv', title: '长命女 · 春日宴', author: '冯延巳', dynasty: '五代', genre: '词', collection: '阳春集', tags: ['祝愿', '情长', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《阳春集》）', text: '春日宴，绿酒一杯歌一遍。再拜陈三愿：一愿郎君千岁，二愿妾身常健，三愿如同梁上燕，岁岁长相见。' }),
  W({ id: 'canon_wudai_tanpo', title: '摊破浣溪沙 · 菡萏香销翠叶残', author: '李璟', dynasty: '五代', genre: '词', collection: '南唐二主词', tags: ['秋思', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本（《南唐二主词》）', text: '菡萏香销翠叶残，西风愁起绿波间。还与韶光共憔悴，不堪看。\n细雨梦回鸡塞远，小楼吹彻玉笙寒。多少泪珠何限恨，倚阑干。' }),
  W({ id: 'canon_wudai_nanxiangzi', title: '南乡子 · 乘彩舫', author: '李珣', dynasty: '五代', genre: '词', collection: '花间集', tags: ['采莲', '岭南', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《花间集》）', text: '乘彩舫，过莲塘，棹歌惊起睡鸳鸯。游女带花偎伴笑，争窈窕，竞折团荷遮晚照。' }),

  // ── 宋 ─────────────────────────────────────────────────────
  W({ id: 'canon_song_shuidiaogetou', title: '水调歌头 · 明月几时有（节选）', author: '苏轼', dynasty: '宋', genre: '词', collection: '宋词三百首', tags: ['中秋', '月亮', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '明月几时有？把酒问青天。不知天上宫阙，今夕是何年。\n人有悲欢离合，月有阴晴圆缺，此事古难全。但愿人长久，千里共婵娟。' }),
  W({ id: 'canon_song_rumengling', title: '如梦令 · 昨夜雨疏风骤', author: '李清照', dynasty: '宋', genre: '词', collection: '宋词三百首', tags: ['惜春', '问答'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '昨夜雨疏风骤，浓睡不消残酒。试问卷帘人，却道海棠依旧。\n知否，知否？应是绿肥红瘦。' }),
  W({ id: 'canon_song_tixilinbi', title: '题西林壁', author: '苏轼', dynasty: '宋', genre: '诗', collection: '', tags: ['哲理', '庐山'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '横看成岭侧成峰，远近高低各不同。\n不识庐山真面目，只缘身在此山中。' }),
  W({ id: 'canon_song_bochuanguazhou', title: '泊船瓜洲', author: '王安石', dynasty: '宋', genre: '诗', collection: '', tags: ['思乡', '炼字'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '京口瓜洲一水间，钟山只隔数重山。\n春风又绿江南岸，明月何时照我还？' }),
  W({ id: 'canon_song_xiaochi', title: '小池', author: '杨万里', dynasty: '宋', genre: '诗', collection: '', tags: ['初夏', '状物'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '泉眼无声惜细流，树阴照水爱晴柔。\n小荷才露尖尖角，早有蜻蜓立上头。' }),
  W({ id: 'canon_song_xiarijueju', title: '夏日绝句', author: '李清照', dynasty: '宋', genre: '诗', collection: '', tags: ['咏史', '气节'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '生当作人杰，死亦为鬼雄。\n至今思项羽，不肯过江东。' }),
  W({ id: 'canon_song_youyuanbuzhi', title: '游园不值', author: '叶绍翁', dynasty: '宋', genre: '诗', collection: '', tags: ['春天', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '应怜屐齿印苍苔，小扣柴扉久不开。\n春色满园关不住，一枝红杏出墙来。' }),
  W({ id: 'canon_song_huichong', title: '惠崇春江晚景 · 其一', author: '苏轼', dynasty: '宋', genre: '诗', collection: '', tags: ['题画', '春天'], popularity: 'normal', difficulty: '入门', source: '通行本', text: '竹外桃花三两枝，春江水暖鸭先知。\n蒌蒿满地芦芽短，正是河豚欲上时。' }),
  W({ id: 'canon_song_yinhu', title: '饮湖上初晴后雨', author: '苏轼', dynasty: '宋', genre: '诗', collection: '', tags: ['西湖', '写景'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '水光潋滟晴方好，山色空蒙雨亦奇。欲把西湖比西子，淡妆浓抹总相宜。' }),
  W({ id: 'canon_song_zengliujingwen', title: '赠刘景文', author: '苏轼', dynasty: '宋', genre: '诗', collection: '', tags: ['秋冬', '勉励'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '荷尽已无擎雨盖，菊残犹有傲霜枝。一年好景君须记，最是橙黄橘绿时。' }),
  W({ id: 'canon_song_nian-nu-jiao', title: '念奴娇 · 赤壁怀古（节选）', author: '苏轼', dynasty: '宋', genre: '词', collection: '宋词三百首', tags: ['怀古', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '大江东去，浪淘尽，千古风流人物。故垒西边，人道是，三国周郎赤壁。乱石穿空，惊涛拍岸，卷起千堆雪。江山如画，一时多少豪杰。' }),
  W({ id: 'canon_song_yuanri', title: '元日', author: '王安石', dynasty: '宋', genre: '诗', collection: '', tags: ['节令', '新年'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '爆竹声中一岁除，春风送暖入屠苏。千门万户曈曈日，总把新桃换旧符。' }),
  W({ id: 'canon_song_guanshu', title: '观书有感 · 其一', author: '朱熹', dynasty: '宋', genre: '诗', collection: '', tags: ['哲理', '读书'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '半亩方塘一鉴开，天光云影共徘徊。问渠那得清如许？为有源头活水来。' }),
  W({ id: 'canon_song_xijiangyue', title: '西江月 · 夜行黄沙道中', author: '辛弃疾', dynasty: '宋', genre: '词', collection: '', tags: ['田园', '夏夜'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '明月别枝惊鹊，清风半夜鸣蝉。稻花香里说丰年，听取蛙声一片。\n七八个星天外，两三点雨山前。旧时茅店社林边，路转溪桥忽见。' }),
  W({ id: 'canon_song_pozhenzi_xinqi', title: '破阵子 · 为陈同甫赋壮词以寄之', author: '辛弃疾', dynasty: '宋', genre: '词', collection: '', tags: ['壮志', '军旅'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '醉里挑灯看剑，梦回吹角连营。八百里分麾下炙，五十弦翻塞外声。沙场秋点兵。\n马作的卢飞快，弓如霹雳弦惊。了却君王天下事，赢得生前身后名。可怜白发生。' }),
  W({ id: 'canon_song_qingyuan', title: '青玉案 · 元夕', author: '辛弃疾', dynasty: '宋', genre: '词', collection: '宋词三百首', tags: ['元宵', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '东风夜放花千树，更吹落、星如雨。宝马雕车香满路。凤箫声动，玉壶光转，一夜鱼龙舞。\n蛾儿雪柳黄金缕，笑语盈盈暗香去。众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。' }),
  W({ id: 'canon_song_youshanxicun', title: '游山西村', author: '陆游', dynasty: '宋', genre: '诗', collection: '', tags: ['田园', '名句'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '莫笑农家腊酒浑，丰年留客足鸡豚。山重水复疑无路，柳暗花明又一村。\n箫鼓追随春社近，衣冠简朴古风存。从今若许闲乘月，拄杖无时夜叩门。' }),
  W({ id: 'canon_song_shier', title: '示儿', author: '陆游', dynasty: '宋', genre: '诗', collection: '', tags: ['遗嘱', '家国'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '死去元知万事空，但悲不见九州同。王师北定中原日，家祭无忘告乃翁。' }),
  W({ id: 'canon_song_shiyiyue', title: '十一月四日风雨大作 · 其二', author: '陆游', dynasty: '宋', genre: '诗', collection: '', tags: ['爱国', '梦境'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '僵卧孤村不自哀，尚思为国戍轮台。夜阑卧听风吹雨，铁马冰河入梦来。' }),
  W({ id: 'canon_song_guolingding', title: '过零丁洋', author: '文天祥', dynasty: '宋', genre: '诗', collection: '', tags: ['气节', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '辛苦遭逢起一经，干戈寥落四周星。山河破碎风飘絮，身世浮沉雨打萍。\n惶恐滩头说惶恐，零丁洋里叹零丁。人生自古谁无死？留取丹心照汗青。' }),
  W({ id: 'canon_song_xiaochu', title: '晓出净慈寺送林子方', author: '杨万里', dynasty: '宋', genre: '诗', collection: '', tags: ['西湖', '夏天'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '毕竟西湖六月中，风光不与四时同。接天莲叶无穷碧，映日荷花别样红。' }),
  W({ id: 'canon_song_huanxisha_yanshu', title: '浣溪沙 · 一曲新词酒一杯', author: '晏殊', dynasty: '宋', genre: '词', collection: '宋词三百首', tags: ['惜时', '名句'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '一曲新词酒一杯，去年天气旧亭台。夕阳西下几时回？\n无可奈何花落去，似曾相识燕归来。小园香径独徘徊。' }),
  W({ id: 'canon_song_yulinling', title: '雨霖铃 · 寒蝉凄切（节选）', author: '柳永', dynasty: '宋', genre: '词', collection: '宋词三百首', tags: ['离别', '名句', '冷门佳作'], popularity: 'notable', difficulty: '深造', source: '通行本', text: '多情自古伤离别，更那堪、冷落清秋节！今宵酒醒何处？杨柳岸，晓风残月。' }),
  W({ id: 'canon_song_yijianmei', title: '一剪梅 · 红藕香残玉簟秋', author: '李清照', dynasty: '宋', genre: '词', collection: '宋词三百首', tags: ['相思', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '红藕香残玉簟秋。轻解罗裳，独上兰舟。云中谁寄锦书来？雁字回时，月满西楼。\n花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头。' }),
  W({ id: 'canon_song_manjianghong', title: '满江红 · 怒发冲冠（节选）', author: '岳飞', dynasty: '宋', genre: '词', collection: '', tags: ['壮志', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '怒发冲冠，凭栏处、潇潇雨歇。抬望眼，仰天长啸，壮怀激烈。三十功名尘与土，八千里路云和月。莫等闲、白了少年头，空悲切。' }),
  W({ id: 'canon_song_sanzijing', title: '三字经（节选）', author: '王应麟（传）', dynasty: '宋', genre: '蒙学', collection: '三字经', tags: ['蒙学', '劝学'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '人之初，性本善。性相近，习相远。苟不教，性乃迁。教之道，贵以专。\n昔孟母，择邻处。子不学，断机杼。' }),
  W({ id: 'canon_song_cunwan', title: '村晚', author: '雷震', dynasty: '宋', genre: '诗', collection: '千家诗', tags: ['牧童', '黄昏', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《千家诗》）', text: '草满池塘水满陂，山衔落日浸寒漪。牧童归去横牛背，短笛无腔信口吹。' }),
  W({ id: 'canon_song_xiangcunsiyue', title: '乡村四月', author: '翁卷', dynasty: '宋', genre: '诗', collection: '', tags: ['田园', '农事', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《全宋诗》）', text: '绿遍山原白满川，子规声里雨如烟。乡村四月闲人少，才了蚕桑又插田。' }),
  W({ id: 'canon_song_zhinan', title: '绝句 · 古木阴中', author: '志南', dynasty: '宋', genre: '诗', collection: '千家诗', tags: ['春天', '杏花', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《千家诗》）', text: '古木阴中系短篷，杖藜扶我过桥东。沾衣欲湿杏花雨，吹面不寒杨柳风。' }),

  // ── 元 ─────────────────────────────────────────────────────
  W({ id: 'canon_yuan_tianjingsha', title: '天净沙 · 秋思', author: '马致远', dynasty: '元', genre: '曲', collection: '', tags: ['羁旅', '秋景', '名句'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '枯藤老树昏鸦，小桥流水人家，古道西风瘦马。\n夕阳西下，断肠人在天涯。' }),
  W({ id: 'canon_yuan_momei', title: '墨梅', author: '王冕', dynasty: '元', genre: '诗', collection: '', tags: ['题画', '品格'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '吾家洗砚池头树，朵朵花开淡墨痕。\n不要人夸好颜色，只留清气满乾坤。' }),
  W({ id: 'canon_yuan_baimei', title: '白梅', author: '王冕', dynasty: '元', genre: '诗', collection: '', tags: ['咏物', '品格', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《竹斋集》）', text: '冰雪林中著此身，不同桃李混芳尘。忽然一夜清香发，散作乾坤万里春。' }),
  W({ id: 'canon_yuan_shanpo-yang', title: '山坡羊 · 潼关怀古', author: '张养浩', dynasty: '元', genre: '曲', collection: '', tags: ['怀古', '民生', '名句'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '峰峦如聚，波涛如怒，山河表里潼关路。望西都，意踌躇。\n伤心秦汉经行处，宫阙万间都做了土。兴，百姓苦；亡，百姓苦。' }),
  W({ id: 'canon_yuan_tianjingsha_qiu', title: '天净沙 · 秋', author: '白朴', dynasty: '元', genre: '曲', collection: '', tags: ['秋景', '散曲', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《天籁集》附）', text: '孤村落日残霞，轻烟老树寒鸦，一点飞鸿影下。青山绿水，白草红叶黄花。' }),
  W({ id: 'canon_yuan_tianjingsha_chun', title: '天净沙 · 春', author: '白朴', dynasty: '元', genre: '曲', collection: '', tags: ['春景', '散曲', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《天籁集》附）', text: '春山暖日和风，阑干楼阁帘栊，杨柳秋千院中。啼莺舞燕，小桥流水飞红。' }),
  W({ id: 'canon_yuan_chenzui', title: '沉醉东风 · 渔夫', author: '白朴', dynasty: '元', genre: '曲', collection: '', tags: ['渔夫', '傲世', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本（《天籁集》附）', text: '黄芦岸白蘋渡口，绿柳堤红蓼滩头。虽无刎颈交，却有忘机友。点秋江白鹭沙鸥。傲杀人间万户侯，不识字烟波钓叟。' }),
  W({ id: 'canon_yuan_shouyangqu', title: '寿阳曲 · 远浦帆归', author: '马致远', dynasty: '元', genre: '曲', collection: '', tags: ['江村', '渔家', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本', text: '夕阳下，酒旆闲，两三航未曾着岸。落花水香茅舍晚，断桥头卖鱼人散。' }),
  W({ id: 'canon_yuan_tilongyang', title: '题龙阳县青草湖', author: '唐珙', dynasty: '元', genre: '诗', collection: '', tags: ['梦', '洞庭', '冷门佳作'], popularity: 'notable', difficulty: '进阶', source: '通行本（《全元诗》）', text: '西风吹老洞庭波，一夜湘君白发多。醉后不知天在水，满船清梦压星河。' }),
  W({ id: 'canon_yuan_moyu', title: '摸鱼儿 · 雁丘词（节选）', author: '元好问', dynasty: '元', genre: '词', collection: '', tags: ['爱情', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本（《遗山先生文集》）', text: '问世间，情为何物，直教生死相许？天南地北双飞客，老翅几回寒暑。\n欢乐趣，离别苦，就中更有痴儿女。君应有语：渺万里层云，千山暮雪，只影向谁去？' }),

  // ── 明 ─────────────────────────────────────────────────────
  W({ id: 'canon_ming_shihuiyin', title: '石灰吟', author: '于谦', dynasty: '明', genre: '诗', collection: '', tags: ['咏物', '气节'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '千锤万凿出深山，烈火焚烧若等闲。\n粉骨碎身浑不怕，要留清白在人间。' }),
  W({ id: 'canon_ming_linjiangxian', title: '临江仙 · 滚滚长江东逝水', author: '杨慎', dynasty: '明', genre: '词', collection: '', tags: ['怀古', '名句'], popularity: 'classic', difficulty: '进阶', source: '通行本（《廿一史弹词》第三段）', text: '滚滚长江东逝水，浪花淘尽英雄。是非成败转头空。\n青山依旧在，几度夕阳红。\n白发渔樵江渚上，惯看秋月春风。一壶浊酒喜相逢。\n古今多少事，都付笑谈中。' }),
  W({ id: 'canon_ming_huaji', title: '画鸡', author: '唐寅', dynasty: '明', genre: '诗', collection: '', tags: ['题画', '状物', '冷门佳作'], popularity: 'notable', difficulty: '蒙学', source: '通行本', text: '头上红冠不用裁，满身雪白走将来。\n平生不敢轻言语，一叫千门万户开。' }),
  W({ id: 'canon_ming_yanzhi', title: '言志', author: '唐寅', dynasty: '明', genre: '诗', collection: '', tags: ['自况', '卖画', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《唐伯虎全集》）', text: '不炼金丹不坐禅，不为商贾不耕田。闲来写就青山卖，不使人间造孽钱。' }),
  W({ id: 'canon_ming_bieyunjian', title: '别云间', author: '夏完淳', dynasty: '明', genre: '诗', collection: '', tags: ['就义', '乡愁'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '三年羁旅客，今日又南冠。无限山河泪，谁言天地宽。\n已知泉路近，欲别故乡难。毅魄归来日，灵旗空际看。' }),
  W({ id: 'canon_ming_tianpingshan', title: '天平山中', author: '杨基', dynasty: '明', genre: '诗', collection: '', tags: ['行旅', '莺啼', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《眉庵集》）', text: '细雨茸茸湿楝花，南风树树熟枇杷。徐行不记山深浅，一路莺啼送到家。' }),
  W({ id: 'canon_ming_chujiao', title: '出郊', author: '杨慎', dynasty: '明', genre: '诗', collection: '', tags: ['田园', '白鹭', '冷门佳作'], popularity: 'notable', difficulty: '蒙学', source: '通行本（《升庵集》）', text: '高田如楼梯，平田如棋局。白鹭忽飞来，点破秧针绿。' }),
  W({ id: 'canon_ming_xunhuyinjun', title: '寻胡隐君', author: '高启', dynasty: '明', genre: '诗', collection: '', tags: ['访友', '春风', '冷门佳作'], popularity: 'notable', difficulty: '蒙学', source: '通行本（《高太史大全集》）', text: '渡水复渡水，看花还看花。春风江上路，不觉到君家。' }),
  W({ id: 'canon_ming_xiangjixuan', title: '项脊轩志（节选）', author: '归有光', dynasty: '明', genre: '文', collection: '古文观止', tags: ['亲情', '纪念'], popularity: 'classic', difficulty: '进阶', source: '通行本', text: '三五之夜，明月半墙，桂影斑驳，风移影动，珊珊可爱。\n庭有枇杷树，吾妻死之年所手植也，今已亭亭如盖矣。' }),
  W({ id: 'canon_ming_huxinting', title: '湖心亭看雪（节选）', author: '张岱', dynasty: '明', genre: '文', collection: '', tags: ['雪景', '痴人'], popularity: 'classic', difficulty: '入门', source: '通行本（《陶庵梦忆》）', text: '雾凇沆砀，天与云与山与水，上下一白。湖上影子，惟长堤一痕、湖心亭一点、与余舟一芥、舟中人两三粒而已。\n莫说相公痴，更有痴似相公者。' }),
  W({ id: 'canon_ming_youxueqionglin', title: '幼学琼林（节选）', author: '程登吉', dynasty: '明', genre: '蒙学', collection: '幼学琼林', tags: ['蒙学', '天地'], popularity: 'normal', difficulty: '蒙学', source: '通行本', text: '混沌初开，乾坤始奠。气之轻清上浮者为天，气之重浊下凝者为地。' }),
  W({ id: 'canon_ming_zengguang', title: '增广贤文（节选）', author: '佚名', dynasty: '明', genre: '蒙学', collection: '增广贤文', tags: ['蒙学', '处世'], popularity: 'normal', difficulty: '蒙学', source: '通行本', text: '昔时贤文，诲汝谆谆。集韵增广，多见多闻。观今宜鉴古，无古不成今。' }),

  // ── 清 ─────────────────────────────────────────────────────
  W({ id: 'canon_qing_zhushi', title: '竹石', author: '郑燮', dynasty: '清', genre: '诗', collection: '', tags: ['题画', '坚韧'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '咬定青山不放松，立根原在破岩中。\n千磨万击还坚劲，任尔东西南北风。' }),
  W({ id: 'canon_qing_jihai_zashi5', title: '己亥杂诗 · 其五', author: '龚自珍', dynasty: '清', genre: '诗', collection: '', tags: ['辞官', '奉献'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '浩荡离愁白日斜，吟鞭东指即天涯。\n落红不是无情物，化作春泥更护花。' }),
  W({ id: 'canon_qing_cunju', title: '村居', author: '高鼎', dynasty: '清', genre: '诗', collection: '', tags: ['春天', '童趣'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '草长莺飞二月天，拂堤杨柳醉春烟。\n儿童散学归来早，忙趁东风放纸鸢。' }),
  W({ id: 'canon_qing_shenglv_qimeng', title: '声律启蒙 · 一东（节选）', author: '车万育', dynasty: '清', genre: '蒙学', collection: '声律启蒙', tags: ['蒙学', '对仗'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '云对雨，雪对风，晚照对晴空。来鸿对去燕，宿鸟对鸣虫。\n三尺剑，六钧弓，岭北对江东。人间清暑殿，天上广寒宫。\n两岸晓烟杨柳绿，一园春雨杏花红。' }),
  W({ id: 'canon_qing_liweng_duiyun', title: '笠翁对韵 · 一东（节选）', author: '李渔', dynasty: '清', genre: '蒙学', collection: '笠翁对韵', tags: ['蒙学', '对仗'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '天对地，雨对风。大陆对长空。山花对海树，赤日对苍穹。\n雷隐隐，雾濛濛。日下对天中。风高秋月白，雨霁晚霞红。' }),
  W({ id: 'canon_qing_dizigu', title: '弟子规（节选）', author: '李毓秀', dynasty: '清', genre: '蒙学', collection: '弟子规', tags: ['蒙学', '修身'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '弟子规，圣人训。首孝悌，次谨信。泛爱众，而亲仁。有余力，则学文。' }),
  W({ id: 'canon_qing_zhuzijiaxun', title: '朱子家训（节选）', author: '朱柏庐', dynasty: '清', genre: '蒙学', collection: '朱子家训', tags: ['蒙学', '治家'], popularity: 'normal', difficulty: '蒙学', source: '通行本', text: '黎明即起，洒扫庭除，要内外整洁。既昏便息，关锁门户，必亲自检点。\n一粥一饭，当思来处不易；半丝半缕，恒念物力维艰。' }),
  W({ id: 'canon_qing_changxiangsi', title: '长相思 · 山一程', author: '纳兰性德', dynasty: '清', genre: '词', collection: '', tags: ['乡愁', '边塞'], popularity: 'classic', difficulty: '入门', source: '通行本（《纳兰词》）', text: '山一程，水一程，身向榆关那畔行，夜深千帐灯。\n风一更，雪一更，聒碎乡心梦不成，故园无此声。' }),
  W({ id: 'canon_qing_mulanhua', title: '木兰花 · 拟古决绝词柬友（节选）', author: '纳兰性德', dynasty: '清', genre: '词', collection: '', tags: ['爱情', '名句'], popularity: 'classic', difficulty: '入门', source: '通行本（《纳兰词》）', text: '人生若只如初见，何事秋风悲画扇。等闲变却故人心，却道故人心易变。' }),
  W({ id: 'canon_qing_suojian', title: '所见', author: '袁枚', dynasty: '清', genre: '诗', collection: '', tags: ['牧童', '蝉'], popularity: 'classic', difficulty: '蒙学', source: '通行本（《随园诗话》所载）', text: '牧童骑黄牛，歌声振林樾。意欲捕鸣蝉，忽然闭口立。' }),
  W({ id: 'canon_qing_tai', title: '苔', author: '袁枚', dynasty: '清', genre: '诗', collection: '', tags: ['咏物', '自励', '冷门佳作'], popularity: 'notable', difficulty: '蒙学', source: '通行本（《随园诗话》所载）', text: '白日不到处，青春恰自来。苔花如米小，也学牡丹开。' }),
  W({ id: 'canon_qing_lunshi', title: '论诗 · 其二', author: '赵翼', dynasty: '清', genre: '诗', collection: '', tags: ['论诗', '才人'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '李杜诗篇万口传，至今已觉不新鲜。江山代有才人出，各领风骚数百年。' }),
  W({ id: 'canon_qing_jihai_zashi125', title: '己亥杂诗 · 其一百二十五', author: '龚自珍', dynasty: '清', genre: '诗', collection: '', tags: ['变革', '人才'], popularity: 'classic', difficulty: '入门', source: '通行本', text: '九州生气恃风雷，万马齐喑究可哀。我劝天公重抖擞，不拘一格降人才。' }),
  W({ id: 'canon_qing_zhouye', title: '舟夜书所见', author: '查慎行', dynasty: '清', genre: '诗', collection: '', tags: ['夜泊', '渔灯'], popularity: 'classic', difficulty: '蒙学', source: '通行本', text: '月黑见渔灯，孤光一点萤。微微风簇浪，散作满河星。' }),
  W({ id: 'canon_qing_dujiang', title: '题秋江独钓图', author: '王士祯', dynasty: '清', genre: '诗', collection: '', tags: ['独钓', '九个一', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《渔洋山人精华录》）', text: '一蓑一笠一扁舟，一丈丝纶一寸钩。一曲高歌一樽酒，一人独钓一江秋。' }),
  W({ id: 'canon_qing_tihongloumeng', title: '题红楼梦（满纸荒唐言）', author: '曹雪芹', dynasty: '清', genre: '诗', collection: '', tags: ['自题', '辛酸', '冷门佳作'], popularity: 'notable', difficulty: '入门', source: '通行本（《红楼梦》第一回）', text: '满纸荒唐言，一把辛酸泪。都云作者痴，谁解其中味。' }),
];
